54:   public analyzePortfolio(holdings: Holding[], currentPrices: Record<string, Asset>): PortfolioAnalysis {
55:     let totalValue = 0;
56:     let totalCost = 0;
57:     const sectorMap: Record<string, number> = {};
58:     const assetTypeMap: Record<'stock' | 'fund', number> = { stock: 0, fund: 0 };
59:     
60:     // Process holdings
61:     holdings.forEach(holding => {
62:       const asset = currentPrices[holding.symbol.toUpperCase()];
63:       const currentPrice = asset ? asset.price : holding.avgCost;
64:       const value = holding.quantity * currentPrice;
65:       const cost = holding.quantity * holding.avgCost;
66:       
67:       totalValue += value;
68:       totalCost += cost;
69:       
70:       // Sector Allocation
71:       const sector = asset ? asset.sector : 'Other';
72:       sectorMap[sector] = (sectorMap[sector] || 0) + value;
73:       
74:       // Asset Type Allocation
75:       const type = asset ? asset.type : 'stock';
76:       assetTypeMap[type] += value;
77:     });
78: 
79:     const totalGainLoss = totalValue - totalCost;
80:     const totalGainLossPercent = totalCost > 0 ? (totalGainLoss / totalCost) * 100 : 0;
81: 
82:     // Calculate allocations
83:     const sectorAllocations = Object.keys(sectorMap).map(sector => ({
84:       sector,
85:       value: sectorMap[sector],
86:       percentage: totalValue > 0 ? (sectorMap[sector] / totalValue) * 100 : 0
87:     })).sort((a, b) => b.value - a.value);
88: 
89:     const assetAllocations = [
90:       { type: 'stock' as const, value: assetTypeMap.stock, percentage: totalValue > 0 ? (assetTypeMap.stock / totalValue) * 100 : 0 },
91:       { type: 'fund' as const, value: assetTypeMap.fund, percentage: totalValue > 0 ? (assetTypeMap.fund / totalValue) * 100 : 0 }
92:     ];
93: 
94:     // Determine Risk Score & Level
95:     // Base rule: Stocks represent higher risk than funds.
96:     const stockRatio = totalValue > 0 ? (assetTypeMap.stock / totalValue) : 0.5;
97:     let riskScore = Math.round(stockRatio * 100);
98:     
99:     // Adjust risk score by sector concentration
100:     if (sectorAllocations.length > 0 && sectorAllocations[0].percentage > 50) {
101:       riskScore = Math.min(100, riskScore + 15); // penalize concentration
102:     }
103:     
104:     let riskLevel: 'ต่ำ' | 'ปานกลาง' | 'สูง' = 'ปานกลาง';
105:     if (riskScore < 35) riskLevel = 'ต่ำ';
106:     else if (riskScore > 70) riskLevel = 'สูง';
107: 
108:     // Calculate Diversification Score (0-100)
109:     // High score means many sectors and balanced asset types
110:     let diversificationScore = 100;
111:     if (holdings.length === 0) {
112:       diversificationScore = 0;
113:     } else {
114:       // Penalty for concentration in top sector
115:       if (sectorAllocations.length > 0) {
116:         const topSectorPercent = sectorAllocations[0].percentage;
117:         diversificationScore -= (topSectorPercent - 20) * 0.8; // Lose points if top sector > 20%
118:       }
119:       // Penalty for few holdings
120:       if (holdings.length < 3) diversificationScore -= 30;
121:       else if (holdings.length < 5) diversificationScore -= 15;
122:       
123:       // Penalty for missing asset types
124:       if (assetTypeMap.stock === 0 || assetTypeMap.fund === 0) {
125:         diversificationScore -= 20;
126:       }
127:       
128:       diversificationScore = Math.max(10, Math.min(100, Math.round(diversificationScore)));
129:     }
130: 
131:     // Generate Warnings
132:     const warnings: string[] = [];
133:     if (holdings.length > 0) {
134:       if (assetTypeMap.stock / totalValue > 0.85) {
135:         warnings.push('พอร์ตของคุณมีสัดส่วนหุ้นสูงมาก (>85%) ซึ่งมีความผันผวนสูงมาก ควรเพิ่มกองทุนรวมตราสารหนี้หรือกองทุนรวมต่างประเทศเพื่อลดความเสี่ยง');
136:       }
137:       if (sectorAllocations.length > 0 && sectorAllocations[0].percentage > 50) {
138:         warnings.push(`มีการกระจุกตัวในกลุ่มอุตสาหกรรม "${sectorAllocations[0].sector}" มากเกินไป (${sectorAllocations[0].percentage.toFixed(1)}%) แนะนำกระจายไปยังอุตสาหกรรมอื่น`);
139:       }
140:       if (holdings.length <= 2) {
141:         warnings.push('พอร์ตของคุณมีจำนวนสินทรัพย์น้อยเกินไป (ต่ำกว่า 3 ชิ้น) ควรเพิ่มความหลากหลายเพื่อลดความเสี่ยงเฉพาะตัวของหุ้นแต่ละตัว');
142:       }
143:       
144:       // Individual holding concentration warning
145:       holdings.forEach(h => {
146:         const assetPrice = currentPrices[h.symbol.toUpperCase()]?.price || h.avgCost;
147:         const val = h.quantity * assetPrice;
148:         if (totalValue > 0 && (val / totalValue) > 0.4) {
149:           warnings.push(`หุ้น/กองทุน "${h.symbol.toUpperCase()}" มีสัดส่วนมากกว่า 40% ของพอร์ตทั้งหมด ความผันผวนของสินทรัพย์นี้จะส่งผลกระทบต่อพอร์ตค่อนข้างสูง`);
150:         }
151:       });
152:     } else {
153:       warnings.push('ยังไม่มีรายการลงทุนในพอร์ต เริ่มต้นเพิ่มรายการหุ้นหรือกองทุนรวมได้เลย!');
154:     }
155: 
156:     // Generate Dynamic Suggestions
157:     const suggestions = RECOMMENDATION_ITEMS.filter(item => {
158:       // Don't recommend what they already own
159:       const ownsItem = holdings.some(h => h.symbol.toUpperCase() === item.symbol);
160:       if (ownsItem) return false;
161: 
162:       // Customize suggestions based on portfolio needs
163:       if (riskLevel === 'สูง' && item.type === 'stock' && item.symbol === 'NVDA') {
164:         return false; // Don't suggest high-risk stock if already high risk, suggest funds instead
165:       }
166:       if (riskLevel === 'ต่ำ' && item.type === 'stock' && item.symbol === 'NVDA') {
167:         return false; // Low risk target shouldn't buy tech growth stocks
168:       }
169:       return true;
170:     }).slice(0, 3); // Pick top 3 recommendations
171: 
172:     return {
173:       totalValue,
174:       totalCost,
175:       totalGainLoss,
176:       totalGainLossPercent,
177:       riskScore,
178:       riskLevel,
179:       diversificationScore,
180:       sectorAllocations,
181:       assetAllocations,
182:       warnings,
183:       suggestions
184:     };
185:   }
