11: /** Ensure the cache directory exists */
12: async function ensureCacheDir() {
13:   try {
14:     await fs.mkdir(CACHE_DIR, { recursive: true });
15:   } catch (e) {
16:     // ignore if it already exists
17:   }
18: }
19: 
20: /** Build a file name from a cache key (URL‑safe) */
21: function keyToFilename(key) {
22:   // simple base64 encoding to avoid illegal characters
23:   const safe = Buffer.from(key).toString("base64url");
24:   return path.join(CACHE_DIR, `${safe}.json`);
25: }
26: 
27: /** Set a value in cache
28:  * @param {string} key – unique identifier for the entry
29:  * @param {any} value – data to store (will be JSON‑stringified)
30:  * @param {number} [ttlMs=30*60*1000] – time‑to‑live in milliseconds
31:  */
32: export async function setCache(key, value, ttlMs = 30 * 60 * 1000) {
33:   await ensureCacheDir();
34:   const expiresAt = Date.now() + ttlMs;
35:   const payload = { value, expiresAt };
36:   const filePath = keyToFilename(key);
37:   await fs.writeFile(filePath, JSON.stringify(payload), "utf8");
38: }
